insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Oltre il binario: l''esadecimale', 'Base 16, gruppi di 4 bit, conversioni e colori #RRGGBB in HTML e CSS.', 'contenuti/lezioni/esadecimale.html', 'contenuti/lezioni/esadecimale.pdf', now() - interval '1 day' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/esadecimale.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Numeri decimali e binari', 'Il sistema posizionale, i bit e le conversioni a mano tra decimale e binario.', 'contenuti/lezioni/numeri-binari.html', 'contenuti/lezioni/numeri-binari.pdf', now() - interval '1 day' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/numeri-binari.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Le conversioni con Calc', 'Divisioni successive con QUOZIENTE e RESTO, verifica con le funzioni di conversione, un convertitore sul foglio.', 'contenuti/lezioni/conversioni-con-calc.html', 'contenuti/lezioni/conversioni-con-calc.pdf', now() - interval '1 day' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/conversioni-con-calc.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'I sistemi di elaborazione', 'Dati e informazioni, hardware, architettura di von Neumann, CPU e ciclo fetch-decode-execute, gerarchia delle memorie e periferiche, con Gestione attività, il mistero dei GB del disco e un vero programma nel Little Man Computer.', 'contenuti/lezioni/sistemi-di-elaborazione.html', 'contenuti/lezioni/sistemi-di-elaborazione.pdf', now() - interval '1 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/sistemi-di-elaborazione.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il software', 'Software di base e applicativo, sistema operativo, linguaggio macchina, assembly e alto livello, compilatori e interpreti, Java con bytecode e JVM, licenze proprietarie, freeware e open source, con errori di compilazione ed esecuzione su OnlineGDB.', 'contenuti/lezioni/software-e-linguaggi.html', 'contenuti/lezioni/software-e-linguaggi.pdf', now() - interval '2 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/software-e-linguaggi.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'I sistemi di numerazione', 'Sistemi non posizionali e posizionali, la regola per qualsiasi base, conversioni da e verso la base 10, somme in binario con i riporti e trucchi per i conti a mente, con la console del browser e la calcolatrice da programmatore.', 'contenuti/lezioni/basi-di-numerazione.html', 'contenuti/lezioni/basi-di-numerazione.pdf', now() - interval '3 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/basi-di-numerazione.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Ottale ed esadecimale al lavoro', 'Ottale ed esadecimale come scrittura corta dei bit, conversioni rapide passando dal binario, permessi dei file Unix, indirizzi di memoria, indirizzi MAC, colori con trasparenza e firme dei file, con JSLinux, ipconfig e HexEd.it.', 'contenuti/lezioni/ottale-ed-esadecimale.html', 'contenuti/lezioni/ottale-ed-esadecimale.pdf', now() - interval '4 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/ottale-ed-esadecimale.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Laboratorio: la codifica dei numeri', 'Laboratorio di conversioni e operazioni tra basi con la calcolatrice da programmatore, la console del browser e un convertitore scritto in Java su OnlineGDB, seguito passo passo con Java Tutor e messo alla prova con una tabella di test.', 'contenuti/lezioni/laboratorio-codifica-numeri.html', 'contenuti/lezioni/laboratorio-codifica-numeri.pdf', now() - interval '5 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/laboratorio-codifica-numeri.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Numeri con il segno', 'Modulo e segno, complemento a 1 e complemento a 2 su 8 bit, somme e sottrazioni in binario, overflow con la calcolatrice in modalità Programmatore e con il tipo byte di Java, la storia di Ariane 5 e i limiti degli interi di oggi, dal contatore di YouTube all''AI quantizzata a 8 bit.', 'contenuti/lezioni/numeri-interi-relativi.html', 'contenuti/lezioni/numeri-interi-relativi.pdf', now() - interval '6 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/numeri-interi-relativi.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Numeri con la virgola', 'Numeri binari con la virgola, perché 0,1 è periodico in binario, virgola fissa e virgola mobile, il float IEEE 754 a 32 bit codificato a mano e con il FloatConverter, precisione ed errori di arrotondamento nella console e in Java, Infinity e NaN, il Patriot del 1991 e i formati ridotti usati dall''AI.', 'contenuti/lezioni/numeri-reali-virgola-mobile.html', 'contenuti/lezioni/numeri-reali-virgola-mobile.pdf', now() - interval '7 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/numeri-reali-virgola-mobile.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il debugger e le variabili', 'Laboratorio in Java: variabili int, double, char e boolean, esecuzione passo passo con Java Tutor, breakpoint e step over nel debugger di OnlineGDB, divisione intera, overflow di int con il fattoriale, 0.1 + 0.2, casting e Math.round, con la falena di Grace Hopper e gli assistenti AI per il codice.', 'contenuti/lezioni/debugger-variabili-java.html', 'contenuti/lezioni/debugger-variabili-java.pdf', now() - interval '8 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/debugger-variabili-java.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Dalle lettere ai numeri', 'Il codice ASCII e l''ordinamento per codice, le tabelle a 8 bit e il mojibake, Unicode e i code point, UTF-8 da 1 a 4 byte codificato a mano e osservato con HexEd.it, emoji con modificatori e ZWJ, la lunghezza delle stringhe nella console, i token dei modelli linguistici e gli attacchi con lettere sosia.', 'contenuti/lezioni/codifica-caratteri.html', 'contenuti/lezioni/codifica-caratteri.pdf', now() - interval '9 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/codifica-caratteri.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Le immagini raster', 'Pixel, risoluzione e ppi, profondità di colore, modelli RGB e CMYK, peso di un''immagine non compressa, kB e KiB, compressione RLE con e senza perdita, la prima foto digitale di Kirsch, con il contagocce e la pixel art in Photopea e il calcolatore del peso in Calc.', 'contenuti/lezioni/immagini-raster.html', 'contenuti/lezioni/immagini-raster.pdf', now() - interval '10 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/immagini-raster.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Laboratorio: i file immagine', 'JPEG, PNG, GIF e WebP a confronto: la gara della compressione con Squoosh, logo contro foto in Photopea, come lavora il JPEG, firme dei file e intestazione PNG lette con HexEd.it, little-endian, file travestiti e metadati EXIF e C2PA.', 'contenuti/lezioni/laboratorio-file-immagine.html', 'contenuti/lezioni/laboratorio-file-immagine.pdf', now() - interval '11 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/laboratorio-file-immagine.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Le immagini vettoriali', 'Grafica vettoriale e raster a confronto, Sketchpad e le curve di Bézier, il formato SVG scritto a mano con rect, circle, polygon, path e text, il sistema di coordinate con la y verso il basso, accessibilità con title e desc, rasterizzazione in Photopea e SVG scritti dall''AI.', 'contenuti/lezioni/immagini-vettoriali.html', 'contenuti/lezioni/immagini-vettoriali.pdf', now() - interval '12 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/immagini-vettoriali.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Le immagini in movimento', 'Fotogrammi e frame rate, da Muybridge allo streaming, il peso di un video non compresso, fotogrammi I, P e B, bitrate, codec e contenitori, streaming adattivo, con una GIF animata su ezgif, le proprietà di un video, i calcoli in Calc e le Statistiche per nerd di YouTube.', 'contenuti/lezioni/immagini-in-movimento.html', 'contenuti/lezioni/immagini-in-movimento.pdf', now() - interval '13 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/immagini-in-movimento.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'I suoni', 'Frequenza e ampiezza, campionamento e quantizzazione, il teorema di Nyquist-Shannon, valori reali di telefono, CD e studio, peso e bitrate di un audio, compressione senza e con perdita, MIDI, con il test dell''udito, un''onda campionata in Calc e il riconoscimento vocale con l''AI.', 'contenuti/lezioni/suono-digitale.html', 'contenuti/lezioni/suono-digitale.pdf', now() - interval '14 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/suono-digitale.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Laboratorio: i file audio', 'Registrare, tagliare, sfumare e normalizzare la voce con AudioMass, il clipping, gli effetti come calcoli sui campioni, WAV contro MP3, l''intestazione WAV letta con HexEd.it, la sfida del messaggio al contrario, consenso e soppressione del rumore con l''AI.', 'contenuti/lezioni/laboratorio-file-audio.html', 'contenuti/lezioni/laboratorio-file-audio.pdf', now() - interval '15 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/laboratorio-file-audio.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Intelligenza artificiale e computer vision', 'Immagini come numeri, i compiti della computer vision, la convoluzione per trovare i bordi in Calc, reti neurali e addestramento, Fei-Fei Li e ImageNet, un classificatore con Teachable Machine, test set e matrice di confusione, bias nei dati, esempi avversari, GDPR e AI Act.', 'contenuti/lezioni/computer-vision.html', 'contenuti/lezioni/computer-vision.pdf', now() - interval '16 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/computer-vision.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Ingegneria del software', 'Perché programmare non basta: la crisi del software e la conferenza NATO del 1968, bug famosi (Ariane 5, Mars Climate Orbiter, Patriot), le 8 caratteristiche di qualità ISO/IEC 25010, i tipi di manutenzione, Margaret Hamilton e l''Apollo 11, con bug da scovare in Java su OnlineGDB e la pagella di un''app in Calc.', 'contenuti/lezioni/ingegneria-del-software.html', 'contenuti/lezioni/ingegneria-del-software.pdf', now() - interval '17 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/ingegneria-del-software.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il ciclo di vita del software', 'Le fasi del ciclo di vita, requisiti funzionali e non funzionali scritti in modo verificabile, i modelli a cascata (e la sorpresa dell''articolo di Royce), iterativo, incrementale e a spirale, i livelli di test e i valori al limite, con i test Java dell''anno bisestile e il piano a incrementi in Excalidraw.', 'contenuti/lezioni/modelli-ciclo-di-vita.html', 'contenuti/lezioni/modelli-ciclo-di-vita.pdf', now() - interval '18 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/modelli-ciclo-di-vita.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Agile, Scrum e Kanban', 'Il Manifesto agile del 2001 e i suoi valori, Scrum con ruoli, eventi e artefatti, le user story con i criteri di accettazione, Kanban e i limiti WIP, il burndown chart, con il backlog dell''app della gita, una user story in Java, una sfida a squadre con i post-it e un burndown in Calc.', 'contenuti/lezioni/agile-scrum-kanban.html', 'contenuti/lezioni/agile-scrum-kanban.pdf', now() - interval '19 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/agile-scrum-kanban.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La gestione dei progetti', 'Progetto e vincoli, la WBS, attività, durate e dipendenze, il diagramma di Gantt, il percorso critico e lo scorrimento, la legge di Brooks e i canali di comunicazione, il registro dei rischi, con la WBS in Excalidraw e Gantt e rischi in Calc o Google Fogli.', 'contenuti/lezioni/gestione-progetti-gantt.html', 'contenuti/lezioni/gestione-progetti-gantt.pdf', now() - interval '20 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/gestione-progetti-gantt.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il World Wide Web', 'Internet e web, la proposta di Tim Berners-Lee al CERN nel 1989, client e server, DNS, le parti di un URL, richieste e risposte HTTP con i codici di stato, la scheda Network dei DevTools e come funzionano i motori di ricerca.', 'contenuti/lezioni/world-wide-web.html', 'contenuti/lezioni/world-wide-web.pdf', now() - interval '21 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/world-wide-web.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Gli elementi base di HTML', 'Tag, elementi e attributi, lo scheletro di una pagina, titoli, paragrafi, formattazione del testo ed entità, annidamento corretto, con la prima pagina scritta nel Blocco note, CodePen e il validatore W3C.', 'contenuti/lezioni/html-elementi-base.html', 'contenuti/lezioni/html-elementi-base.pdf', now() - interval '22 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/html-elementi-base.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Link, immagini, elenchi e tabelle', 'Link assoluti, relativi e interni, percorsi con ../, immagini con un buon testo alternativo, elenchi puntati, numerati e annidati, tabelle con caption, th, colspan e rowspan, fino all''orario della 3E in HTML.', 'contenuti/lezioni/html-link-immagini-tabelle.html', 'contenuti/lezioni/html-link-immagini-tabelle.pdf', now() - interval '23 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/html-link-immagini-tabelle.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Lo stile della pagina web: i CSS', 'Contenuto e presentazione, la proposta di Håkon Wium Lie, sintassi delle regole, CSS in linea, interni ed esterni, colori in esadecimale e rgb(), proprietà per testo, font, bordi, elenchi e tabelle, con CodePen, DevTools e il validatore CSS.', 'contenuti/lezioni/css-primi-stili.html', 'contenuti/lezioni/css-primi-stili.pdf', now() - interval '24 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/css-primi-stili.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La mia prima pagina web', 'Laboratorio: una pagina personale scritta a mano con Blocco note, dallo scheletro con DOCTYPE e charset a elenchi, link, immagini e tabelle, fino al foglio di stile esterno, con gli errori tipici di estensioni, percorsi e maiuscole.', 'contenuti/lezioni/laboratorio-prima-pagina-web.html', 'contenuti/lezioni/laboratorio-prima-pagina-web.pdf', now() - interval '25 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/laboratorio-prima-pagina-web.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Classi, id e selettori CSS', 'Selettori di classe e di id, discendenti, figli, di gruppo e di attributo, pseudo-classi come :hover, :nth-child e :has(), la cascata con importanza, specificità e ordine, l''ereditarietà e il calcolo della specificità a mano, con una sfida su CodePen.', 'contenuti/lezioni/css-classi-id-specificita.html', 'contenuti/lezioni/css-classi-id-specificita.pdf', now() - interval '26 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/css-classi-id-specificita.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il box model e i layout CSS', 'Contenuto, padding, bordo e margine, i conti delle dimensioni con content-box e border-box, il collasso dei margini, display block, inline, inline-block e none, la colonna centrata con margin auto e il layout a due colonne con float, misurati con i DevTools.', 'contenuti/lezioni/css-box-model-layout.html', 'contenuti/lezioni/css-box-model-layout.pdf', now() - interval '27 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/css-box-model-layout.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Un piccolo sito con layout', 'Laboratorio in coppia: dal wireframe su carta o Excalidraw a un sito di tre pagine con intestazione, menu orizzontale con voce attiva, due colonne, piè di pagina e un solo foglio di stile, con link relativi, debug guidato e collaudo incrociato.', 'contenuti/lezioni/laboratorio-layout-sito.html', 'contenuti/lezioni/laboratorio-layout-sito.pdf', now() - interval '28 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/laboratorio-layout-sito.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Gli strumenti dello sviluppatore web', 'Lezione online: editor di testo e VS Code con Emmet, CodePen e JSFiddle senza account, i pannelli dei DevTools (Stili, Calcolato, Rete, modalità dispositivo), i validatori HTML e CSS del W3C e un uso critico degli assistenti AI, con la revisione di codice generato.', 'contenuti/lezioni/strumenti-sviluppo-web.html', 'contenuti/lezioni/strumenti-sviluppo-web.pdf', now() - interval '29 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/strumenti-sviluppo-web.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'HTML semantico e accessibilità', 'I tag semantici di HTML5 (header, nav, main, article, section, aside, footer), la gerarchia dei titoli, pulsanti ed etichette veri, il testo alternativo informativo, decorativo e funzionale, le WCAG e la frase di Tim Berners-Lee sul web per tutti, con prove al validatore W3C, a WAVE, alla tastiera e al Narratore di Windows.', 'contenuti/lezioni/html-semantico-accessibilita.html', 'contenuti/lezioni/html-semantico-accessibilita.pdf', now() - interval '30 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/html-semantico-accessibilita.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il posizionamento degli elementi', 'Il flusso normale e i cinque valori di position (static, relative, absolute, fixed, sticky), il primo antenato posizionato, la coppia padre relative e figlio absolute, header sticky e pulsanti fixed, z-index e contesto di impilamento, con laboratori su CodePen e DevTools.', 'contenuti/lezioni/posizionamento-css.html', 'contenuti/lezioni/posizionamento-css.pdf', now() - interval '31 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/posizionamento-css.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il layout CSS Flexbox', 'Contenitore ed elementi flex, asse principale e trasversale, flex-direction, justify-content, align-items, flex-wrap e gap, il calcolo a mano di flex-grow, Flexbox Froggy, l''ispettore Flexbox di DevTools e Flexbox nelle app per telefono.', 'contenuti/lezioni/css-flexbox.html', 'contenuti/lezioni/css-flexbox.pdf', now() - interval '32 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/css-flexbox.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il layout CSS Grid', 'Righe, colonne, gap e l''unità fr con il calcolo a mano delle larghezze, linee e span, grid-template-areas con i tag semantici, Grid Garden, un calendario di novembre 2026 costruito in Grid, subgrid e la storia della griglia da Müller-Brockmann ai browser.', 'contenuti/lezioni/css-grid.html', 'contenuti/lezioni/css-grid.pdf', now() - interval '33 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/css-grid.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Progettare un sito responsive', 'I tre ingredienti del responsive di Ethan Marcotte, il meta viewport e i 980 pixel finti, pixel CSS e devicePixelRatio con i calcoli, la strategia mobile first, le media query e il loro ordine, immagini fluide e srcset, tema scuro, con la modalità dispositivo dei DevTools.', 'contenuti/lezioni/responsive-mobile-first.html', 'contenuti/lezioni/responsive-mobile-first.pdf', now() - interval '34 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/responsive-mobile-first.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Laboratorio: CineTerza responsive', 'Il sito del cineforum di classe costruito passo passo: wireframe in tre misure, HTML semantico, Flexbox per intestazione e locandine, grid-template-areas per la pagina, galleria su 1, 2 e 3 colonne, il calcolo di fr, il collaudo con DevTools, tastiera e validatori W3C.', 'contenuti/lezioni/sito-responsive-flexbox-grid.html', 'contenuti/lezioni/sito-responsive-flexbox-grid.pdf', now() - interval '35 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/sito-responsive-flexbox-grid.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Audio, video e contenuti incorporati', 'Dal plugin Flash a HTML5: i tag audio e video con più sorgenti, la regola dell''autoplay muto, sottotitoli WebVTT con track scritti in CodePen, sottotitoli, trascrizione e audiodescrizione, iframe di YouTube e OpenStreetMap con title e lazy loading, la privacy degli embed e i sottotitoli automatici con l''AI.', 'contenuti/lezioni/multimedia-embedded.html', 'contenuti/lezioni/multimedia-embedded.pdf', now() - interval '36 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/multimedia-embedded.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Responsive senza media query', 'Il layout intrinseco: unità fluide, min(), max() e clamp() con i calcoli, flex-wrap con flex-basis, la griglia repeat(auto-fit, minmax()) e la differenza con auto-fill, le container query, la storia delle tecniche di impaginazione e quando le media query servono ancora.', 'contenuti/lezioni/responsive-senza-media-query.html', 'contenuti/lezioni/responsive-senza-media-query.pdf', now() - interval '37 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/responsive-senza-media-query.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il ruolo del sistema operativo', 'Che cos''è il sistema operativo, macchina estesa e gestore di risorse, le risorse che governa e l''astrazione, dall''operatore degli anni ''50 alla NPU di oggi, con Gestione attività, Monitoraggio risorse e i cluster del file system.', 'contenuti/lezioni/ruolo-sistema-operativo.html', 'contenuti/lezioni/ruolo-sistema-operativo.pdf', now() - interval '38 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/ruolo-sistema-operativo.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Kernel e shell', 'Kernel monolitici, microkernel e ibridi, la shell grafica e a riga di comando, le chiamate di sistema e le pipe, con i primi comandi in cmd, PowerShell e in un Linux vero dentro il browser.', 'contenuti/lezioni/kernel-e-shell.html', 'contenuti/lezioni/kernel-e-shell.pdf', now() - interval '39 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/kernel-e-shell.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'User mode e kernel mode', 'Perché serve la protezione, le due modalità della CPU, i ring di x86, il passaggio con le chiamate di sistema, la memoria divisa in esadecimale e i due tipi di crash, da Multics e Dijkstra alle schermate blu del 2024, con Gestione attività, PowerShell e Monitoraggio affidabilità.', 'contenuti/lezioni/user-mode-kernel-mode.html', 'contenuti/lezioni/user-mode-kernel-mode.pdf', now() - interval '40 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/user-mode-kernel-mode.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Tipologie di sistemi operativi', 'Sistemi batch, multiprogrammati, time sharing, real time hard e soft, distribuiti, mobili ed embedded, con il calcolo dell''utilizzo della CPU, l''allarme 1202 dell''Apollo 11 e una prova dei tempi di reazione.', 'contenuti/lezioni/tipologie-sistemi-operativi.html', 'contenuti/lezioni/tipologie-sistemi-operativi.pdf', now() - interval '41 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/tipologie-sistemi-operativi.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'I sistemi operativi in commercio', 'La storia di Unix, l''annuncio di Linux del 1991, le famiglie di Windows, macOS, Linux, Android, iOS e ChromeOS, licenze proprietarie e libere, con JSLinux, la build di Windows e un censimento dei sistemi della classe.', 'contenuti/lezioni/sistemi-operativi-commercio.html', 'contenuti/lezioni/sistemi-operativi-commercio.pdf', now() - interval '42 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/sistemi-operativi-commercio.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Le prestazioni del sistema operativo', 'Utilizzo della CPU, throughput, tempi di completamento, di attesa e di risposta calcolati a mano, il collo di bottiglia, Gestione attività, Monitoraggio risorse e un core sotto sforzo, uptime, top e free in JSLinux, fino ai token al secondo dei chatbot.', 'contenuti/lezioni/prestazioni-sistema-operativo.html', 'contenuti/lezioni/prestazioni-sistema-operativo.pdf', now() - interval '43 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/prestazioni-sistema-operativo.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La gestione della CPU: i processi', 'Programma e processo, il modello a cinque stati, il PCB, il cambio di contesto e i thread, con tasklist e taskkill in Windows, ps, top e /proc in JSLinux per vedere gli stati R, S e T, e i processi del browser.', 'contenuti/lezioni/processi-stati-pcb.html', 'contenuti/lezioni/processi-stati-pcb.pdf', now() - interval '44 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/processi-stati-pcb.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Gli algoritmi di scheduling dei processi', 'FCFS, SJF, priorità e Round Robin con diagrammi di Gantt e calcolo dei tempi di attesa, completamento e risposta, l''effetto convoglio, la starvation e l''aging, un foglio Calc per l''FCFS con tempi di arrivo, il Gantt a celle colorate e il gioco a squadre in cui la classe fa la CPU.', 'contenuti/lezioni/scheduling-processi.html', 'contenuti/lezioni/scheduling-processi.pdf', now() - interval '45 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/scheduling-processi.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La gestione degli interrupt', 'Polling e interrupt a confronto con i conti, interrupt hardware, eccezioni e chiamate di sistema, i sei passi della gestione e il vettore delle interruzioni, il timer che rende possibile il Round Robin, priorità e l''allarme 1202 di Apollo 11, con /proc/interrupts in JSLinux, gli IRQ di Windows e gli eventi del browser.', 'contenuti/lezioni/gestione-interrupt.html', 'contenuti/lezioni/gestione-interrupt.pdf', now() - interval '46 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/gestione-interrupt.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La memoria fisica e virtuale', 'Gerarchia delle memorie con tempi di accesso reali, indirizzi fisici e potenze di 2, indirizzi logici e traduzione con registro base e limite, l''idea di memoria virtuale con il file di paging, fino alla RAM che serve ai modelli di intelligenza artificiale.', 'contenuti/lezioni/memoria-fisica-virtuale.html', 'contenuti/lezioni/memoria-fisica-virtuale.pdf', now() - interval '47 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/memoria-fisica-virtuale.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'L''allocazione contigua a partizioni', 'Partizioni fisse e variabili, frammentazione interna ed esterna, first fit, best fit e worst fit svolti a mano e in un torneo a squadre, compattazione, simulazione in Calc e in Java.', 'contenuti/lezioni/allocazione-partizioni.html', 'contenuti/lezioni/allocazione-partizioni.pdf', now() - interval '48 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/allocazione-partizioni.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'L''allocazione non contigua a paginazione statica', 'Pagine e frame, tabella delle pagine, traduzione degli indirizzi in decimale e in esadecimale, operazioni sui bit nella console del browser, dimensione delle tabelle e TLB, frammentazione interna, un traduttore in Java e le pagine nei server dei chatbot.', 'contenuti/lezioni/paginazione-statica.html', 'contenuti/lezioni/paginazione-statica.pdf', now() - interval '49 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/paginazione-statica.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La memoria virtuale a paginazione dinamica', 'Paginazione su richiesta e bit di validità, i passi di un page fault, tabelle FIFO, LRU e OPT svolte a mano e in Calc, l''anomalia di Belady scoperta con un programma Java, thrashing e working set, la memoria virtuale di Atlas e dei modelli di AI sul PC.', 'contenuti/lezioni/paginazione-dinamica.html', 'contenuti/lezioni/paginazione-dinamica.pdf', now() - interval '50 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/paginazione-dinamica.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La memoria virtuale a segmentazione', 'Segmenti di codice, dati, stack e heap, tabella dei segmenti con base, limite e permessi, segmentation fault, i segmenti di un processo Linux e il controllo dei limiti in Java, confronto con la paginazione e segmentazione paginata, fino alla sicurezza della memoria di oggi.', 'contenuti/lezioni/segmentazione-memoria.html', 'contenuti/lezioni/segmentazione-memoria.pdf', now() - interval '51 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/segmentazione-memoria.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il file system', 'File, cartelle e metadati, percorsi assoluti e relativi in Windows e Linux, permessi rwx e chmod in ottale, FAT32, exFAT, NTFS ed ext4 a confronto, da Unix nel 1974 alle app di Android, con Esplora file e un Linux vero nel browser.', 'contenuti/lezioni/file-system-permessi.html', 'contenuti/lezioni/file-system-permessi.pdf', now() - interval '52 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/file-system-permessi.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Dove finiscono i byte sul disco', 'Blocchi e cluster, frammentazione interna ed esterna, allocazione contigua, concatenata e indicizzata, la FAT e l''i-node con il calcolo dei puntatori, fino a SSD, TRIM ed extent, con Calc, JSLinux e le dimensioni su disco di Windows.', 'contenuti/lezioni/allocazione-spazio-disco.html', 'contenuti/lezioni/allocazione-spazio-disco.pdf', now() - interval '53 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/allocazione-spazio-disco.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La gestione delle periferiche', 'Periferiche a blocchi e a caratteri, controller, driver e firmware, polling, interrupt e DMA con un calcolo, buffering, rimozione sicura e spooling, dall''Apollo 11 alle NPU, con Gestione dispositivi, la coda di stampa e /dev in Linux.', 'contenuti/lezioni/gestione-periferiche.html', 'contenuti/lezioni/gestione-periferiche.pdf', now() - interval '54 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/gestione-periferiche.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Proteggere i dati', 'Protezione e sicurezza, riservatezza, integrità e disponibilità, utenti, permessi e minimo privilegio, autenticazione a due fattori e forza delle password con un calcolo, backup 3-2-1 verificato con l''hash, malware, WannaCry, etica e legge, fino a phishing con l''AI e passkey.', 'contenuti/lezioni/protezione-sicurezza-dati.html', 'contenuti/lezioni/protezione-sicurezza-dati.pdf', now() - interval '55 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/protezione-sicurezza-dati.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'DomoDash: il cruscotto della casa intelligente', 'Progetto di gruppo in sei settimane: scenario, ruoli e Kanban, schizzo e wireframe in Excalidraw, sensori e attuatori come card in HTML e CSS Grid, dati in JSON trasformati in pagina con un piccolo script, test di accessibilità e presentazione finale con griglia di valutazione.', 'contenuti/lezioni/progetto-casa-intelligente.html', 'contenuti/lezioni/progetto-casa-intelligente.pdf', now() - interval '56 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/progetto-casa-intelligente.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Il nostro Comune a raggi X', 'Progetto di gruppo in sei settimane: rifiuti ed energia del proprio Comune con dati aperti veri di ISPRA, GSE e Terna citati con fonte e licenza, wireframe mobile first, grafici accessibili da Calc, layout responsive con Flexbox, Grid e media query, collaudo e presentazione con griglia di valutazione.', 'contenuti/lezioni/progetto-sito-ambiente.html', 'contenuti/lezioni/progetto-sito-ambiente.pdf', now() - interval '57 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/progetto-sito-ambiente.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'La seconda vita dei rifiuti elettronici', 'Che cos''è un RAEE, materie preziose e sostanze pericolose, i numeri veri del mondo e dell''Italia calcolati in Calc, i gruppi R1-R5, centro di raccolta, uno contro uno e uno contro zero, economia circolare, diritto alla riparazione e come cancellare i dati prima di dare via un telefono.', 'contenuti/lezioni/raee-rifiuti-elettronici.html', 'contenuti/lezioni/raee-rifiuti-elettronici.pdf', now() - interval '58 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/raee-rifiuti-elettronici.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Copiare, citare, creare', 'La legge italiana sul diritto d''autore, l''articolo 70 per la scuola, le licenze Creative Commons e i siti con licenza propria, i diritti sulle registrazioni musicali, le licenze del software, l''AI nella legge 132/2025 e nell''AI Act, con crediti scritti in HTML, ricerca inversa delle immagini e una licenza per la propria opera.', 'contenuti/lezioni/diritto-autore-in-rete.html', 'contenuti/lezioni/diritto-autore-in-rete.pdf', now() - interval '59 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/diritto-autore-in-rete.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '3g', 'Sicuri al lavoro, a partire dal laboratorio', 'Il D.Lgs. 81/2008 e la Costituzione, lo studente equiparato al lavoratore, le figure della sicurezza a scuola, la matrice dei rischi R = P × D in Calc, rischio elettrico e potenza delle ciabatte, estintori, cartelli ed evacuazione, i diritti al videoterminale e la sicurezza in PCTO.', 'contenuti/lezioni/sicurezza-lavoro-laboratorio.html', 'contenuti/lezioni/sicurezza-lavoro-laboratorio.pdf', now() - interval '60 minutes' where not exists (select 1 from materials where class_id = '3g' and url = 'contenuti/lezioni/sicurezza-lavoro-laboratorio.html');
